solution.solution.cpp:
// How many instructions the countdown program executes when the counter starts at `start`.
int instructionsRun(int start)
{
    // LOAD runs once. Each trip round the loop runs JUMPZ, SUB, STORE and JUMP.
    // The final JUMPZ, the one that finds zero, and the HALT run once each.
    return 1 + 4 * start + 2;
}

unitTests:
TEST("a counter that starts at zero") { CHECK_EQ(instructionsRun(0), 3); }
TEST("one trip round the loop") { CHECK_EQ(instructionsRun(1), 7); }
TEST("the lesson's example, starting at three") { CHECK_EQ(instructionsRun(3), 15); }
TEST("a longer count") { CHECK_EQ(instructionsRun(10), 43); CHECK_EQ(instructionsRun(250), 1003); }

